-- v4.3.6 platform-native Agent bootstrap, provisioning, LLM and runtime contracts.
MERGE INTO CX_PLATFORM_CAPABILITIES d USING (SELECT 'agent_provisioning' CAPABILITY_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY)
WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,MANDATORY) VALUES (s.CAPABILITY_KEY,'N');
MERGE INTO CX_PLATFORM_CAPABILITY_DEPENDENCIES d USING (SELECT 'agent_provisioning' CAPABILITY_KEY,'agents' DEPENDS_ON_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY AND d.DEPENDS_ON_KEY=s.DEPENDS_ON_KEY)
WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,DEPENDS_ON_KEY) VALUES (s.CAPABILITY_KEY,s.DEPENDS_ON_KEY);
MERGE INTO CX_PLATFORM_CAPABILITY_DEPENDENCIES d USING (SELECT 'agent_provisioning' CAPABILITY_KEY,'audit_write' DEPENDS_ON_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY AND d.DEPENDS_ON_KEY=s.DEPENDS_ON_KEY)
WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,DEPENDS_ON_KEY) VALUES (s.CAPABILITY_KEY,s.DEPENDS_ON_KEY);
DECLARE
  PROCEDURE ddl(s VARCHAR2) IS BEGIN EXECUTE IMMEDIATE s; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF; END;
BEGIN
  ddl('CREATE TABLE CX_NATIVE_BOOTSTRAP (BOOTSTRAP_KEY VARCHAR2(64) PRIMARY KEY, BOOTSTRAP_VERSION VARCHAR2(32) NOT NULL, STATUS VARCHAR2(32) NOT NULL, STARTED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, COMPLETED_AT TIMESTAMP, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_AGENT_TEMPLATES (TEMPLATE_ID VARCHAR2(128) PRIMARY KEY, TEMPLATE_KEY VARCHAR2(128) UNIQUE NOT NULL, DISPLAY_NAME VARCHAR2(256) NOT NULL, TEMPLATE_KIND VARCHAR2(64) NOT NULL, CONTENT_JSON CLOB NOT NULL, CONTENT_DIGEST VARCHAR2(64) NOT NULL, LOCKED_FIELDS_JSON CLOB NOT NULL, STATUS VARCHAR2(32) DEFAULT ''DRAFT'' NOT NULL, MANAGED CHAR(1) DEFAULT ''N'' NOT NULL, CREATED_BY VARCHAR2(128) NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_NATIVE_MANIFESTS (MANIFEST_ID VARCHAR2(128) PRIMARY KEY, MANIFEST_KEY VARCHAR2(128) NOT NULL, VERSION NUMBER(10,0) DEFAULT 1 NOT NULL, MANIFEST_KIND VARCHAR2(32) NOT NULL, CONTENT_JSON CLOB NOT NULL, CONTENT_DIGEST VARCHAR2(64) NOT NULL, SIGNATURE VARCHAR2(256) NOT NULL, SIGNATURE_STATUS VARCHAR2(32) DEFAULT ''UNVERIFIED'' NOT NULL, STATUS VARCHAR2(32) DEFAULT ''DRAFT'' NOT NULL, MANAGED CHAR(1) DEFAULT ''N'' NOT NULL, CREATED_BY VARCHAR2(128) NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT UK_CX_NATIVE_MANIFEST UNIQUE (MANIFEST_KEY,VERSION))');
  ddl('CREATE TABLE CX_NATIVE_AGENTS (AGENT_ID VARCHAR2(128) PRIMARY KEY, SOURCE VARCHAR2(32) NOT NULL, AGENT_KIND VARCHAR2(64) NOT NULL, TEMPLATE_ID VARCHAR2(128), OWNER_PRINCIPAL_ID VARCHAR2(128), STATUS VARCHAR2(32) NOT NULL, ACTIVATION_STATE VARCHAR2(32) NOT NULL, LLM_PROFILE_ID VARCHAR2(128), DEPLOYMENT_TARGET_ID VARCHAR2(128), SECURITY_DOMAIN_ID VARCHAR2(128) DEFAULT ''DEFAULT'' NOT NULL, IS_PROTECTED CHAR(1) DEFAULT ''N'' NOT NULL, CREATED_BY VARCHAR2(128) NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE INDEX IDX_CX_NATIVE_AGENT_STATE ON CX_NATIVE_AGENTS(STATUS,ACTIVATION_STATE)');
  ddl('CREATE TABLE CX_LLM_PROVIDER_PROFILES (PROFILE_ID VARCHAR2(128) PRIMARY KEY, PROFILE_KEY VARCHAR2(128) UNIQUE NOT NULL, PROVIDER_URL VARCHAR2(512) NOT NULL, MODEL_ID VARCHAR2(256) NOT NULL, API_KEY_CIPHER CLOB, SECRET_PRESENT CHAR(1) DEFAULT ''N'' NOT NULL, HEALTH_STATE VARCHAR2(32) DEFAULT ''UNKNOWN'' NOT NULL, STATUS VARCHAR2(32) DEFAULT ''ACTIVE'' NOT NULL, VERSION NUMBER(19,0) DEFAULT 1 NOT NULL, APPROVED_FOR_JSON CLOB DEFAULT ''[]'' NOT NULL, UPDATED_BY VARCHAR2(128), UPDATE_REASON VARCHAR2(2000), CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_DEPLOYMENT_TARGETS (TARGET_ID VARCHAR2(128) PRIMARY KEY, TARGET_KEY VARCHAR2(128) UNIQUE NOT NULL, TARGET_TYPE VARCHAR2(64) NOT NULL, CONFIG_JSON CLOB NOT NULL, STATUS VARCHAR2(32) DEFAULT ''ACTIVE'' NOT NULL, MANAGED CHAR(1) DEFAULT ''N'' NOT NULL, CREATED_BY VARCHAR2(128) NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_NATIVE_PROVISION_REQUESTS (REQUEST_ID VARCHAR2(128) PRIMARY KEY, AGENT_NAME VARCHAR2(256) NOT NULL, APPLICANT_PRINCIPAL_ID VARCHAR2(128) NOT NULL, OWNER_PRINCIPAL_ID VARCHAR2(128) NOT NULL, TEMPLATE_KEY VARCHAR2(128) NOT NULL, LLM_PROFILE_ID VARCHAR2(128), DEPLOYMENT_TARGET_ID VARCHAR2(128), ISOLATION_LEVEL VARCHAR2(32) NOT NULL, CLASSIFICATION VARCHAR2(32) NOT NULL, PURPOSE VARCHAR2(2000) NOT NULL, REASON VARCHAR2(2000) NOT NULL, STATUS VARCHAR2(32) DEFAULT ''APPROVAL_PENDING'' NOT NULL, DECIDED_BY VARCHAR2(128), DECISION_REASON VARCHAR2(2000), DECIDED_AT TIMESTAMP, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE INDEX IDX_CX_NATIVE_REQUEST_STATUS ON CX_NATIVE_PROVISION_REQUESTS(STATUS,CREATED_AT)');
  ddl('CREATE TABLE CX_RUNTIME_WORKERS (WORKER_ID VARCHAR2(128) PRIMARY KEY, NODE_ID VARCHAR2(128) NOT NULL, TARGET_TYPE VARCHAR2(64) NOT NULL, STATUS VARCHAR2(32) DEFAULT ''ONLINE'' NOT NULL, CAPABILITIES_JSON CLOB NOT NULL, LEASE_EXPIRES_AT TIMESTAMP, FENCING_TOKEN NUMBER(19,0) DEFAULT 1 NOT NULL, LAST_SEEN_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_RUNTIME_EXECUTIONS (EXECUTION_ID VARCHAR2(128) PRIMARY KEY, AGENT_ID VARCHAR2(128) NOT NULL, TARGET_ID VARCHAR2(128), ISOLATION_LEVEL VARCHAR2(32) NOT NULL, STATUS VARCHAR2(32) DEFAULT ''PENDING'' NOT NULL, WORKER_ID VARCHAR2(128), NODE_ID VARCHAR2(128), CONTEXT_DIGEST VARCHAR2(64), WORKSPACE_REF VARCHAR2(256), TOKEN_DIGEST VARCHAR2(128), INPUT_JSON CLOB DEFAULT ''{}'' NOT NULL, OUTPUT_JSON CLOB, LEASE_EXPIRES_AT TIMESTAMP, FENCING_TOKEN NUMBER(19,0) DEFAULT 1 NOT NULL, FAILURE_REASON VARCHAR2(2000), STARTED_AT TIMESTAMP, COMPLETED_AT TIMESTAMP, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE INDEX IDX_CX_RUNTIME_EXEC_LEASE ON CX_RUNTIME_EXECUTIONS(STATUS,LEASE_EXPIRES_AT,CREATED_AT)');
  ddl('CREATE TABLE CX_EXTERNAL_AGENT_POLICY (POLICY_KEY VARCHAR2(64) PRIMARY KEY, STATE VARCHAR2(32) DEFAULT ''ENABLED'' NOT NULL, VERSION NUMBER(19,0) DEFAULT 1 NOT NULL, UPDATED_BY VARCHAR2(128), REASON VARCHAR2(2000) NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_EXTERNAL_AGENT_POLICY_HISTORY (HISTORY_ID VARCHAR2(128) PRIMARY KEY, POLICY_KEY VARCHAR2(64) NOT NULL, FROM_STATE VARCHAR2(32) NOT NULL, TO_STATE VARCHAR2(32) NOT NULL, RESULT_VERSION NUMBER(19,0) NOT NULL, CHANGED_BY VARCHAR2(128) NOT NULL, REASON VARCHAR2(2000) NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
END;
/
MERGE INTO CX_EXTERNAL_AGENT_POLICY d USING (SELECT 'external_agent_registration' POLICY_KEY FROM DUAL) s ON (d.POLICY_KEY=s.POLICY_KEY)
WHEN NOT MATCHED THEN INSERT (POLICY_KEY,STATE,VERSION,UPDATED_BY,REASON) VALUES (s.POLICY_KEY,'ENABLED',1,'SYSTEM_BOOTSTRAP','preserve existing Skill-first registration');
